set-variable.value:
@{
            var u = new JObject();
            u["Hate"] = 2;
            u["Violence"] = 3;
            u["Sexual"] = 3;
            u["SelfHarm"] = 3;
            return u;
        }

@{
            var r = new JObject();
            r["conversacion"] = "";
            r["ultimo_usuario"] = "";
            try {
                var body = context.Request.Body?.As<JObject>(true);
                var messages = body != null ? body["messages"] as JArray : null;
                if (messages != null) {
                    var todo = new System.Text.StringBuilder();
                    string ultimoUsuario = "";
                    foreach (var t in messages) {
                        var m = t as JObject;
                        if (m == null) {
                            continue;
                        }
                        var c = m["content"];
                        string texto = "";
                        if (c != null) {
                            if (c.Type == JTokenType.String) {
                                texto = (string)c;
                            } else if (c.Type == JTokenType.Array) {
                                var partes = new System.Text.StringBuilder();
                                foreach (var p in (JArray)c) {
                                    var po = p as JObject;
                                    if (po != null && (string)po["type"] == "text") {
                                        partes.AppendLine((string)po["text"] ?? "");
                                    }
                                }
                                texto = partes.ToString();
                            }
                        }
                        if (string.IsNullOrWhiteSpace(texto)) {
                            continue;
                        }
                        todo.AppendLine(texto);
                        if ((string)m["role"] == "user") {
                            ultimoUsuario = texto;
                        }
                    }
                    int max = 10000;
                    string conv = todo.ToString();
                    if (conv.Length > max) {
                        conv = conv.Substring(conv.Length - max);
                    }
                    if (ultimoUsuario.Length > max) {
                        ultimoUsuario = ultimoUsuario.Substring(ultimoUsuario.Length - max);
                    }
                    r["conversacion"] = conv;
                    r["ultimo_usuario"] = ultimoUsuario;
                }
            } catch {
            }
            return r;
        }

@{
            try {
                var b = context.Request.Body?.As<JObject>(true);
                return b != null && b["stream"] != null && b["stream"].Type == JTokenType.Boolean && (bool)b["stream"];
            } catch {
                return false;
            }
        }

send-request.set-body:
@{
                var textos = context.Variables.GetValueOrDefault<JObject>("csTextosPrompt", new JObject());
                var b = new JObject();
                b["text"] = (string)textos["conversacion"] ?? "";
                b["categories"] = new JArray("Hate", "SelfHarm", "Sexual", "Violence");
                b["outputType"] = "EightSeverityLevels";
                b["blocklistNames"] = new JArray("blocklist1");
                b["haltOnBlocklistHit"] = false;
                return b.ToString();
            }

set-variable.value:
@{
            var r = new JObject();
            var porCategoria = new JObject();
            var coincidencias = new JArray();
            int maxSev = -1;
            string maxCat = "";
            bool ok = false;
            try {
                IResponse resp = context.Variables.ContainsKey("csAnalyzeResponse") ? (IResponse)context.Variables["csAnalyzeResponse"] : null;
                if (resp != null && resp.StatusCode == 200) {
                    var json = resp.Body.As<JObject>(true);
                    var analysis = json["categoriesAnalysis"] as JArray;
                    if (analysis != null) {
                        ok = true;
                        foreach (var item in analysis) {
                            int sev = (int)item["severity"];
                            string cat = (string)item["category"];
                            porCategoria[cat] = sev;
                            if (sev > maxSev) {
                                maxSev = sev;
                                maxCat = cat;
                            }
                        }
                    }
                    var matches = json["blocklistsMatch"] as JArray;
                    if (matches != null) {
                        foreach (var m in matches) {
                            coincidencias.Add((string)m["blocklistItemText"]);
                        }
                    }
                }
            } catch {
            }
            r["ok"] = ok;
            r["max_severidad"] = maxSev;
            r["categoria_max"] = maxCat;
            r["por_categoria"] = porCategoria;
            r["blocklist"] = coincidencias;
            return r;
        }

@{
            var p = (JObject)context.Variables["csPre"];
            var umbrales = (JObject)context.Variables["csUmbrales"];
            if (!(bool)p["ok"]) {
                return "sin_analisis";
            }
            int maxSev = (int)p["max_severidad"];
            if (((JArray)p["blocklist"]).Count > 0) {
                return "bloqueo_esperado";
            }
            foreach (var prop in ((JObject)p["por_categoria"]).Properties()) {
                int umbral = umbrales[prop.Name] != null ? (int)umbrales[prop.Name] : 3;
                if ((int)prop.Value >= umbral) {
                    return "bloqueo_esperado";
                }
            }
            if (maxSev >= 1) {
                return "riesgo_leve";
            }
            return "limpio";
        }

inbound.set-body:
@{
            try {
                var b = context.Request.Body.As<JObject>(true);
                if (b != null && b["model"] != null) {
                    b["model"] = (string)context.Variables["modeloDestino"];
                }
                return b != null ? b.ToString() : context.Request.Body.As<string>(true);
            } catch {
                return context.Request.Body != null ? context.Request.Body.As<string>(true) : "";
            }
        }

