set-header.value:
@{
                                var porCategoria = new JObject();
                                try {
                                    IResponse resp = context.Variables.ContainsKey("csSalidaResponse") ? (IResponse)context.Variables["csSalidaResponse"] : null;
                                    if (resp != null && resp.StatusCode == 200) {
                                        var json = resp.Body.As<JObject>(true);
                                        var analysis = json["categoriesAnalysis"] as JArray;
                                        if (analysis != null) {
                                            foreach (var item in analysis) {
                                                porCategoria[(string)item["category"]] = (int)item["severity"];
                                            }
                                        }
                                    }
                                } catch {
                                }
                                return porCategoria.ToString(Newtonsoft.Json.Formatting.None);
                            }

set-variable.value:
@{
            if (!context.Variables.ContainsKey("csTextoRespuesta")) {
                return false;
            }
            string t = ((string)context.Variables["csTextoRespuesta"] ?? "").Trim().ToLowerInvariant();
            if (t.Length == 0) {
                return false;
            }
            if (t.Length > 250) {
                t = t.Substring(0, 250);
            }
            string[] frases = new string[] {
                "lo siento", "no puedo", "no voy a", "no es posible ayudarte", "no puedo ayudar",
                "no puedo cumplir", "no puedo crear", "no puedo escribir", "no me es posible",
                "i'm sorry", "i am sorry", "i can't", "i cannot", "i won't", "i will not", "sorry, but"
            };
            foreach (var f in frases) {
                if (t.Contains(f)) {
                    return true;
                }
            }
            return false;
        }

return-response.set-body:
@{
                        var p = (JObject)context.Variables["csPre"];
                        var umbrales = (JObject)context.Variables["csUmbrales"];
                        var nombres = new JObject();
                        nombres["SelfHarm"] = "autolesion";
                        nombres["Hate"] = "discurso de odio";
                        nombres["Violence"] = "violencia";
                        nombres["Sexual"] = "contenido sexual";

                        string cat = (string)p["categoria_max"] ?? "";
                        int sev = (int)p["max_severidad"];
                        string nombre = nombres[cat]?.ToString() ?? cat;
                        int umbral = umbrales[cat] != null ? (int)umbrales[cat] : 3;

                        var maxEntrada = new JObject();
                        maxEntrada["categoria"] = string.IsNullOrEmpty(cat) ? "No determinada" : cat;
                        maxEntrada["severidad"] = sev;

                        var body = new JObject();
                        body["blocked"] = true;
                        body["gateway"] = "APIM Content Safety Gateway";
                        body["causa_bloqueo"] = "negativa_del_modelo_con_riesgo";
                        body["causas_detectadas"] = new JArray("negativa_del_modelo_con_riesgo");
                        body["mensaje"] = (string)context.Variables["csNivel"] == "sin_analisis"
                            ? "Tu solicitud fue bloqueada por el gateway: no se pudo medir la severidad de la entrada y el modelo se nego a responder."
                            : $"Tu solicitud fue bloqueada por el gateway: la entrada tiene riesgo de nivel {sev} en la categoria \"{nombre}\" (umbral de bloqueo directo: {umbral}) y el modelo {(string)context.Variables["modeloDestino"]} se nego a responder, lo que confirma que el contenido solicitado no es aceptable.";
                        body["categoria_detectada"] = string.IsNullOrEmpty(cat) ? "No determinada" : cat;
                        body["severidad_detectada"] = sev >= 0 ? sev.ToString() : "No determinada";
                        body["severidad_maxima_entrada"] = maxEntrada;
                        body["severidades_por_categoria"] = p["por_categoria"];
                        body["blocklist_coincidencias"] = p["blocklist"];
                        body["prompt_shield_ataque"] = false;
                        body["diagnostico_completo"] = (bool)p["ok"];
                        body["nivel_riesgo"] = (string)context.Variables["csNivel"];
                        body["modelo_enrutado"] = (string)context.Variables["modeloDestino"];
                        body["negativa_del_modelo"] = true;
                        body["escala_severidad"] = "EightSeverityLevels: 0 (nada) a 7 (extremo). Se bloquea cuando la severidad es igual o mayor al umbral de su categoria.";
                        body["umbrales_configurados"] = umbrales;
                        return body.ToString();
                    }

