set-variable.value:
@{
                    string categoria = "";
                    int severidad = -1;
                    var coincidencias = new JArray();
                    bool ataque = false;
                    bool analisisOk = false;
                    bool shieldOk = false;
                    var porCategoria = new JObject();

                    try {
                        IResponse resp = context.Variables.ContainsKey("csAnalyzeResponse") ? (IResponse)context.Variables["csAnalyzeResponse"] : null;
                        if (resp != null && resp.StatusCode == 200) {
                            var json = resp.Body.As<JObject>(true);
                            var analysis = json["categoriesAnalysis"] as JArray;
                            if (analysis != null) {
                                analisisOk = true;
                                foreach (var item in analysis) {
                                    int sev = (int)item["severity"];
                                    string cat = (string)item["category"];
                                    porCategoria[cat] = sev;
                                    if (sev > severidad) {
                                        severidad = sev;
                                        categoria = cat;
                                    }
                                }
                            }
                            var matches = json["blocklistsMatch"] as JArray;
                            if (matches != null) {
                                foreach (var m in matches) {
                                    coincidencias.Add((string)m["blocklistItemText"]);
                                }
                            }
                        }
                    } catch {
                    }

                    try {
                        IResponse shieldResp = context.Variables.ContainsKey("csShieldResponse") ? (IResponse)context.Variables["csShieldResponse"] : null;
                        if (shieldResp != null && shieldResp.StatusCode == 200) {
                            var sj = shieldResp.Body.As<JObject>(true);
                            var upa = sj["userPromptAnalysis"] as JObject;
                            if (upa != null) {
                                shieldOk = true;
                                ataque = (bool)upa["attackDetected"];
                            }
                        }
                    } catch {
                    }

                    var d = new JObject();
                    d["categoria"] = categoria;
                    d["severidad"] = severidad;
                    d["blocklist"] = coincidencias;
                    d["ataque"] = ataque;
                    d["analisis_ok"] = analisisOk;
                    d["shield_ok"] = shieldOk;
                    d["por_categoria"] = porCategoria;
                    return d;
                }

when.set-body:
@{
                  try {
                    var d = (JObject)context.Variables["csDiagnostico"];
                    string categoria = (string)d["categoria"];
                    int severidad = (int)d["severidad"];
                    var coincidencias = (JArray)d["blocklist"];
                    bool ataque = (bool)d["ataque"];
                    bool analisisOk = (bool)d["analisis_ok"];
                    bool shieldOk = (bool)d["shield_ok"];
                    var porCategoria = (JObject)d["por_categoria"];
                    var mensajeOriginal = context.Variables.GetValueOrDefault<string>("csRawMessage", "");
                    int umbralGlobal = 3;

                    var nombresCategoria = new JObject();
                    nombresCategoria["SelfHarm"] = "autolesion";
                    nombresCategoria["Hate"] = "discurso de odio";
                    nombresCategoria["Violence"] = "violencia";
                    nombresCategoria["Sexual"] = "contenido sexual";

                    // Mismos umbrales que los threshold de llm-content-safety (inbound)
                    var umbrales = context.Variables.ContainsKey("csUmbrales") ? (JObject)context.Variables["csUmbrales"] : new JObject();
                    if (umbrales["Hate"] == null) { umbrales["Hate"] = 2; }
                    if (umbrales["Violence"] == null) { umbrales["Violence"] = 3; }
                    if (umbrales["Sexual"] == null) { umbrales["Sexual"] = 3; }
                    if (umbrales["SelfHarm"] == null) { umbrales["SelfHarm"] = 3; }

                    bool superaUmbral = false;
                    string categoriaCausa = "";
                    int severidadCausa = -1;
                    int umbralCausa = umbralGlobal;
                    foreach (var prop in porCategoria.Properties()) {
                        int sev = (int)prop.Value;
                        int umbral = umbrales[prop.Name] != null ? (int)umbrales[prop.Name] : umbralGlobal;
                        if (sev >= umbral && sev > severidadCausa) {
                            superaUmbral = true;
                            categoriaCausa = prop.Name;
                            severidadCausa = sev;
                            umbralCausa = umbral;
                        }
                    }
                    string nombreLegible = superaUmbral ? (nombresCategoria[categoriaCausa]?.ToString() ?? categoriaCausa) : "";

                    bool hayBlocklist = coincidencias.Count > 0;
                    bool diagnosticoCompleto = analisisOk && shieldOk;

                    var causas = new JArray();
                    if (superaUmbral) {
                        causas.Add("categoria_entrada");
                    }
                    if (hayBlocklist) {
                        causas.Add("blocklist");
                    }
                    if (ataque) {
                        causas.Add("prompt_shield");
                    }
                    if (causas.Count == 0) {
                        if (diagnosticoCompleto) {
                            causas.Add("salida_del_modelo_probable");
                        } else {
                            causas.Add("no_determinada");
                        }
                    }
                    string causaPrincipal = (string)causas[0];

                    string nivelTexto = analisisOk
                        ? $" Nivel maximo detectado en la entrada: {severidad} en \"{(nombresCategoria[categoria]?.ToString() ?? categoria)}\" (escala 0-7, umbral {(umbrales[categoria] != null ? (int)umbrales[categoria] : umbralGlobal)})."
                        : "";

                    string mensajeProfesional;
                    if (causaPrincipal == "categoria_entrada") {
                        mensajeProfesional = $"Tu solicitud fue bloqueada porque el contenido evaluado alcanzo un nivel de severidad {severidadCausa} en la categoria \"{nombreLegible}\", igual o superior al umbral de {umbralCausa} configurado en la politica de seguridad de contenido de este servicio.";
                    } else if (causaPrincipal == "blocklist") {
                        mensajeProfesional = "Tu solicitud fue bloqueada porque contiene un termino de la lista de bloqueo (blocklist1) configurada en la politica de seguridad de este servicio." + nivelTexto;
                    } else if (causaPrincipal == "prompt_shield") {
                        mensajeProfesional = "Tu solicitud fue bloqueada por Prompt Shield: se detecto un intento de manipular o saltarse las instrucciones del modelo." + nivelTexto;
                    } else if (causaPrincipal == "salida_del_modelo_probable") {
                        mensajeProfesional = "Tu solicitud no alcanza ningun umbral ni activa la blocklist ni Prompt Shield, pero el gateway la bloqueo. Lo mas probable es que la respuesta generada por el modelo haya alcanzado el umbral en la validacion de salida. Esta causa se deduce por descarte y no se puede confirmar directamente." + nivelTexto;
                    } else {
                        mensajeProfesional = "Tu solicitud fue bloqueada por el filtro de seguridad de contenido de Azure AI Content Safety. No fue posible determinar la causa exacta porque fallo alguna de las consultas de diagnostico; el detalle original de Azure queda incluido para referencia.";
                    }

                    var maxEntrada = new JObject();
                    maxEntrada["categoria"] = string.IsNullOrEmpty(categoria) ? "No determinada" : categoria;
                    maxEntrada["severidad"] = severidad;

                    var body = new JObject();
                    body["blocked"] = true;
                    body["gateway"] = "APIM Content Safety Gateway";
                    body["mensaje"] = mensajeProfesional;
                    body["causa_bloqueo"] = causaPrincipal;
                    body["causas_detectadas"] = causas;
                    body["categoria_detectada"] = superaUmbral ? categoriaCausa : "No determinada";
                    body["severidad_detectada"] = superaUmbral ? severidadCausa.ToString() : "No determinada";
                    body["severidad_maxima_entrada"] = maxEntrada;
                    body["severidades_por_categoria"] = porCategoria;
                    body["blocklist_coincidencias"] = coincidencias;
                    body["prompt_shield_ataque"] = ataque;
                    body["diagnostico_completo"] = diagnosticoCompleto;
                    body["nivel_riesgo"] = context.Variables.GetValueOrDefault<string>("csNivel", "");
                    body["modelo_enrutado"] = context.Variables.GetValueOrDefault<string>("modeloDestino", "");
                    body["escala_severidad"] = "EightSeverityLevels: 0 (nada) a 7 (extremo). Se bloquea cuando la severidad es igual o mayor al umbral de su categoria.";
                    body["umbrales_configurados"] = umbrales;
                    body["detalle_original_azure"] = mensajeOriginal;
                    body["error_source"] = context.LastError?.Source ?? "";
                    body["error_reason"] = context.LastError?.Reason ?? "";

                    return body.ToString();
                  } catch (Exception ex) {
                    var fallback = new JObject();
                    fallback["blocked"] = true;
                    fallback["gateway"] = "APIM Content Safety Gateway";
                    fallback["mensaje"] = "Tu solicitud fue bloqueada por Azure AI Content Safety. No fue posible calcular el diagnostico de la causa.";
                    fallback["causa_bloqueo"] = "no_determinada";
                    fallback["causas_detectadas"] = new JArray("no_determinada");
                    fallback["diagnostico_completo"] = false;
                    fallback["detalle_original_azure"] = context.LastError?.Message ?? "";
                    fallback["error_source"] = context.LastError?.Source ?? "";
                    fallback["error_reason"] = context.LastError?.Reason ?? "";
                    fallback["error_diagnostico"] = ex.Message;
                    return fallback.ToString();
                  }
                }

@{
                    var body = new JObject();
                    body["blocked"] = false;
                    body["servicio_no_disponible"] = true;
                    body["gateway"] = "APIM Content Safety Gateway";
                    body["mensaje"] = "El servicio de Azure AI Content Safety no respondió (error transitorio o blocklist1 inexistente en el recurso; no es un bloqueo de contenido). Reintenta en unos segundos y, si persiste, verifica que blocklist1 exista.";
                    body["detalle_original_azure"] = context.LastError.Message ?? string.Empty;
                    return body.ToString();
                }
